pragma solidity 0.8.3;
pragma experimental ABIEncoderV2;

import "forge-std/Test.sol";
import "../src/WizardPay.sol";

contract PrivilegeEscalationTest is Test {
    WizardPay public wizardPay;
    address public owner = makeAddr("owner");
    address public attacker = makeAddr("attacker");
    uint256 public constant INITIAL_ETHER_CAP = 10 ether;
    ERC20Mock public token;

    function setUp() public {
        vm.startPrank(owner);
        wizardPay = new WizardPay();
        vm.stopPrank();

        // Deploy a mock ERC20 token
        token = new ERC20Mock("TestToken", "TEST");

        // Fund the WizardPay contract with ETH
        vm.deal(address(wizardPay), INITIAL_ETHER_CAP);

        // Mint tokens directly to WizardPay contract
        token.mint(address(wizardPay), 100_000 ether);
    }

    function testTransferETHVulnerability() public {
        uint256 contractBalanceBefore = address(wizardPay).balance;
        uint256 attackerBalanceBefore = attacker.balance;

        // Owner transfers all ETH to attacker
        vm.prank(owner);
        wizardPay.TransferETH(payable(attacker), contractBalanceBefore);

        // Verify privilege escalation - contract drained
        assertEq(address(wizardPay).balance, 0, "All ETH should be drained");
        assertEq(attacker.balance, attackerBalanceBefore + contractBalanceBefore, "Attacker should receive ETH");
    }

    function testTransferERC20Vulnerability() public {
        uint256 contractTokenBalance = token.balanceOf(address(wizardPay));
        uint256 attackerTokenBalanceBefore = token.balanceOf(attacker);

        // Owner transfers all tokens to attacker
        vm.prank(owner);
        wizardPay.transferAnyERC20Tokens(address(token), attacker, contractTokenBalance);

        // Verify privilege escalation - tokens transferred
        assertEq(token.balanceOf(address(wizardPay)), 0, "All tokens should be drained");
        assertEq(token.balanceOf(attacker), attackerTokenBalanceBefore + contractTokenBalance, "Attacker should receive tokens");
    }
}

// Minimal ERC20 implementation for testing
contract ERC20Mock {
    mapping(address => uint256) public balanceOf;
    string public name;
    string public symbol;

    event Transfer(address indexed from, address indexed to, uint256 value);

    constructor(string memory _name, string memory _symbol) {
        name = _name;
        symbol = _symbol;
    }

    function mint(address to, uint256 amount) public {
        balanceOf[to] += amount;
        emit Transfer(address(0), to, amount);
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        require(balanceOf[msg.sender] >= amount, "Insufficient balance");
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        emit Transfer(msg.sender, to, amount);
        return true;
    }
}
